namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            ★
        </span>
    }
    @if (_averageRating > 0)
    {
        <span class="rating-info ms-2 text-muted">
            @_averageRating.ToString("0.0") avg (@_ratingCount ratings)
        </span>
    }
    @if (_submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star:hover,
    .star-rating .star.filled {
        color: #ffc107;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _selectedRating;
    private double _averageRating;
    private int _ratingCount;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe != null)
        {
            _averageRating = recipe.AverageRating;
            _ratingCount = recipe.RatingCount;
        }
    }
}

@page "/"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>RecipeShare - Home</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes from around the world</p>
</div>

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-3 g-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text text-muted">
                        @RecipeService.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="/recipes/@category" class="btn btn-outline-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="text-center mt-5">
    <h3>Have a recipe to share?</h3>
    <a href="/submit" class="btn btn-success btn-lg mt-2">Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Japanese" => "🇯🇵",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

<h1>@Category Recipes</h1>

@if (_recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="list-group">
        @foreach (var recipe in _recipes)
        {
            <a href="/recipe/@recipe.Id" class="list-group-item list-group-item-action">
                <div class="d-flex justify-content-between align-items-center">
                    <h5 class="mb-1">@recipe.Title</h5>
                    @if (recipe.RatingCount > 0)
                    {
                        <span class="badge bg-warning text-dark">
                            ★ @recipe.AverageRating.ToString("0.0")
                        </span>
                    }
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<RecipeShare.Models.Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeShare</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@_recipe.Title - RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <div class="my-3">
        <StarRating RecipeId="@_recipe.Id" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeShare.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

