            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs", Steps = "1. Soak rice noodles in warm water 20 minutes\n2. Make sauce: tamarind, fish sauce, sugar\n3. Press and cube tofu, fry until golden\n4. Scramble eggs in wok\n5. Add noodles and sauce, toss\n6. Add bean sprouts and green onions\n7. Serve with crushed peanuts and lime wedge" },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in skillet\n2. Add taco seasoning and water, simmer\n3. Warm tortillas on a dry pan\n4. Dice tomato and shred lettuce\n5. Assemble tacos with beef and toppings\n6. Serve with salsa and sour cream" },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados\n2. Mash avocado to desired consistency\n3. Finely dice onion, jalapeño, and tomato\n4. Chop cilantro\n5. Mix everything with lime juice and salt\n6. Serve immediately with tortilla chips" },
            new() { Id = 7, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoft-boiled egg\nChashu pork\nGreen onions\nNori\nCorn\nButter", Steps = "1. Bring chicken broth to a simmer\n2. Whisk in miso paste\n3. Cook ramen noodles separately\n4. Slice chashu pork and prepare toppings\n5. Place noodles in bowl, ladle broth over\n6. Arrange toppings: egg, pork, corn, nori\n7. Add a pat of butter and sliced green onions" },
            new() { Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla\nFlour\nBaking soda\nSalt\nChocolate chips", Steps = "1. Cream butter and sugars until fluffy\n2. Beat in eggs and vanilla\n3. Mix flour, baking soda, and salt\n4. Combine wet and dry ingredients\n5. Fold in chocolate chips\n6. Scoop onto baking sheets\n7. Bake at 375°F for 9-11 minutes\n8. Cool on wire rack" },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var recipe = GetById(recipeId);
        if (recipe != null)
        {
            recipe.RatingCount = _ratings[recipeId].Count;
            recipe.AverageRating = _ratings[recipeId].Average();
        }
    }
}
"}

